def error_lines(path):
    with open(path, encoding='utf-8', errors='replace') as f:
        for line in f:
            if ' ERROR ' in line or line.startswith('ERROR'):
                yield line.rstrip('\n')

from contextlib import contextmanager

@contextmanager
def conn(connect_fn):
    c = connect_fn()
    try:
        yield c
    finally:
        c.close()

from functools import lru_cache

@lru_cache(maxsize=128)
def fib(n):
    return n if n < 2 else fib(n - 1) + fib(n - 2)

fib(30)
print(fib.cache_info())

from collections import Counter

def levels(path):
    c = Counter()
    with open(path, encoding='utf-8', errors='replace') as f:
        for line in f:
            parts = line.split(' ', 2)
            if len(parts) >= 2:
                c[parts[1].strip('[]')] += 1
    return c

import time

def throttle(max_per_sec=5):
    min_gap = 1.0 / max_per_sec
    last = [0.0]
    def wait():
        delta = time.perf_counter() - last[0]
        if delta < min_gap:
            time.sleep(min_gap - delta)
        last[0] = time.perf_counter()
    return wait

import functools, time, logging

def timed(fn):
    @functools.wraps(fn)
    def wrapper(*args, **kwargs):
        t0 = time.perf_counter()
        try:
            return fn(*args, **kwargs)
        finally:
            ms = (time.perf_counter() - t0) * 1000
            if ms > 100:
                logging.warning('%s slow: %.1fms', fn.__name__, ms)
    return wrapper

def deco(fn):
    @functools.wraps(fn)
    def wrapper(*a, **kw):
        return fn(*a, **kw)
    return wrapper
